sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var userId = gs.getUserID();

    if (!userId) {
        response.setStatus(401);
        response.setBody({
            success: false,
            message: 'Authentication required'
        });
        return;
    }

    // --------------------------------------------------
    // 1. Cancel any previous ACTIVE QR for this employee
    // --------------------------------------------------
    var oldQr = new GlideRecord('x_1760545_smarta_0_qr_token');
    oldQr.addQuery('employee', userId);
    oldQr.addQuery('status', 'active');
    oldQr.query();

    while (oldQr.next()) {
        oldQr.setValue('status', 'cancelled');
        oldQr.update();
    }

    // --------------------------------------------------
    // 2. Generate secure random one-time token
    // --------------------------------------------------
    var token = GlideSecureRandomUtil.getSecureRandomString(32);

    // --------------------------------------------------
    // 3. Set creation + expiry time
    // --------------------------------------------------
    var createdAt = new GlideDateTime();

    var expiresAt = new GlideDateTime(createdAt);
    expiresAt.addSeconds(20);

    // --------------------------------------------------
    // 4. Create QR Token record
    // --------------------------------------------------
    var qr = new GlideRecord('x_1760545_smarta_0_qr_token');
    qr.initialize();

    qr.setValue('token', token);
    qr.setValue('employee', userId);
    qr.setValue('status', 'active');
    qr.setValue('created_at', createdAt.getValue());
    qr.setValue('expires_at', expiresAt.getValue());

    var qrSysId = qr.insert();

    if (!qrSysId) {
        response.setStatus(500);
        response.setBody({
            success: false,
            message: 'Unable to create attendance QR'
        });
        return;
    }

    // --------------------------------------------------
    // 5. Return token to employee application
    // --------------------------------------------------
    response.setStatus(201);

    response.setBody({
        success: true,
        token: token,
        expires_in: 20,
        expires_at: expiresAt.getValue()
    });

})(request, response);
